playerConnecting.example:
const banned = new Set(['steam:76561198000000001']);

kcds.core.Events.on('playerConnecting', async (request) => {
  const steam = request.getIdentifier('steam');
  if (banned.has(`steam:${steam}`)) {
    request.reject('You are banned from this server.');
  } else if (await serverIsFull()) {
    request.reject('The server is full, try again later.');
  }
});

playerConnecting.exampleCs:
var banned = new HashSet<string> { "steam:76561198000000001" };

Events.On("playerConnecting", async (JsValue request) =>
{
    var steam = request.Call("getIdentifier", "steam");
    if (banned.Contains($"steam:{steam}"))
    {
        request.Call("reject", "You are banned from this server.");
    }
    else if (await serverIsFull())
    {
        request.Call("reject", "The server is full, try again later.");
    }
});

playerConnect.example:
kcds.core.Events.on('playerConnect', (player) => {
  const saved = savedInventories.get(player.steamId);
  if (saved) {
    kcds.players.Inventory.set(player, { items: saved.items, quickslots: saved.quickslots });
  }
});

playerConnect.exampleCs:
Events.On("playerConnect", (Player player) =>
{
    if (savedInventories.TryGetValue(player.SteamId.ToString(), out var saved))
    {
        Inventory.Set(player, new { items = saved["items"], quickslots = saved["quickslots"] });
    }
});

