playerCommand.example:
kcds.core.Events.on('playerCommand', (player, command, args) => {
  if (command.toLowerCase() === 'hello') {
    kcds.core.Chat.sendToPlayer(player, args.join(' ') || 'Hello!', { author: 'Server' });
  }
});

playerCommand.exampleCs:
Events.On("playerCommand", (Player player, string command, string[] args) =>
{
    if (command.ToLowerInvariant() == "hello")
    {
        var reply = args.Length > 0 ? string.Join(" ", args) : "Hello!";
        Chat.SendToPlayer(player, reply, new { author = "Server" });
    }
});

playerStatsChanged.example:
kcds.core.Events.on('playerStatsChanged', (player, changes) => {
  for (const { stat, current } of changes) {
    if (stat === 'hunger' && current < 10) {
      kcds.core.Chat.sendToPlayer(player, 'You are starving.');
    }
  }
});

playerStatsChanged.exampleCs:
Events.On("playerStatsChanged", (Player player, JsValue changes) =>
{
    foreach (var change in changes)
    {
        if (change["stat"].AsString() == "hunger" && change["current"].AsNumber() < 10)
        {
            Chat.SendToPlayer(player, "You are starving.");
        }
    }
});

