chatKey.example:
// client: your own chat window instead of the game's
const { Web, Controls } = kcds.ui;
const chatWindow = Web.open('kcds://resources/my_chat/ui/chat.html', { width: 480, height: 320, visible: false });
kcds.core.Chat.setUIVisible(false);
kcds.core.Events.on('chatKey', () => {
  Web.show(chatWindow);
  Web.focus(chatWindow);
  Controls.showCursor();
});

chatKey.exampleCs:
// client: your own chat window instead of the game's
var chatWindow = Web.Open("kcds://resources/my_chat/ui/chat.html", new { width = 480, height = 320, visible = false });
Chat.SetUIVisible(false);
Events.On("chatKey", () =>
{
    Web.Show(chatWindow);
    Web.Focus(chatWindow);
    Controls.ShowCursor();
});

chatMessage.example:
// client: a notice when someone writes the player's name
