  const name = kcds.players.LocalPlayer?.nickname;
  if (name && message.text.includes(name)) {
    kcds.ui.Hud.showNotification(`${message.author} mentioned you`);
  }
});

chatMessage.exampleCs:
// client: a notice when someone writes the player's name
Events.On("chatMessage", (JsValue message) =>
{
    var name = LocalPlayer.Current!.Nickname;
    if (!string.IsNullOrEmpty(name) && message["text"].Call("includes", name).AsBool())
    {
        Hud.ShowNotification($"{message["author"]} mentioned you");
    }
});

