vendorTrade.example:
kcds.core.Events.on('vendorTrade', (vendorId, player, bought, sold, balance, haggled) => {
  const items = bought.map((line) => `${line.amount} ${line.name}`).join(', ');
  const how = haggled ? 'after haggling' : 'at list price';
  console.info(`${player.nickname} bought ${items} and paid ${-balance} ${how}`);
});

vendorTrade.exampleCs:
Events.On("vendorTrade", (JsValue vendorId, Player player, JsValue bought, JsValue sold, double balance, bool haggled) =>
{
    var items = string.Join(", ", bought.Select((line) => $"{line["amount"].AsInt()} {line["name"].AsString()}"));
    var how = haggled ? "after haggling" : "at list price";
    Log.Info($"{player.Nickname} bought {items} and paid {-balance} {how}");
});

vendorHaggle.example:
// Regulars get up to 10% off; the vendor's own rule answers everyone else.
kcds.core.Events.on('vendorHaggle', (vendorId, player, basket, offered) => {
  if (player.state.get('regular') === true && offered >= basket.price * 0.9) {
    return { accept: true };
  }
});

vendorHaggle.exampleLua:
-- Regulars get up to 10% off; the vendor's own rule answers everyone else.
kcds.core.Events.on("vendorHaggle", function(vendorId, player, basket, offered)
  if player.state:get("regular") == true and offered >= basket.price * 0.9 then
    return { accept = true }
  end
end)

vendorHaggle.exampleCs:
// Regulars get up to 10% off; the vendor's own rule answers everyone else.
Events.On("vendorHaggle", object? (JsValue vendorId, Player player, JsValue basket, double offered) =>
{
    if (player.State.Get("regular").AsBool() && offered >= basket["price"].AsNumber() * 0.9)
    {
        return new { accept = true };
    }
    return null;
});

