  const top = deck.pile('table').at(-1);
  return pieces.length === 1 && (!top || pieces[0].suit === top.suit || pieces[0].rank === top.rank);
});

deckPlayRequest.exampleLua:
-- Prší: the same suit or rank as the top card.
kcds.core.Events.on("deckPlayRequest", function(deck, player, pieces)
  local pile = deck:pile("table")
  local top = pile[#pile]
  return #pieces == 1 and (top == nil or pieces[1].suit == top.suit or pieces[1].rank == top.rank)
end)

deckPlayRequest.exampleCs:
// Prší: the same suit or rank as the top card.
Events.On("deckPlayRequest", object? (JsValue deck, Player player, JsValue pieces) =>
{
    var pile = deck.Call("pile", "table");
    var count = (int)pile["length"].AsNumber();
    if (pieces["length"].AsNumber() != 1)
    {
        return false;
    }
    if (count == 0)
    {
        return true;
    }
    var top = pile[count - 1];
    return pieces[0]["suit"].Is(top["suit"]) || pieces[0]["rank"].Is(top["rank"]);
});

